SELECT 
FROM TBL_FINANCIAL_PRODUCT p
LEFT JOIN TBL_FINANCIAL_CATEGORY c ON p.CATEGORY_ID = c.CATEGORY_ID


        AND p.ORG_ID = #{params.orgId}


        AND p.PRODUCT_CODE LIKE CONCAT('%', #{params.productCode}, '%')


        AND p.PRODUCT_NAME LIKE CONCAT('%', #{params.productName}, '%')


        AND p.PRODUCT_TYPE = #{params.productType}


        AND p.CATEGORY_ID = #{params.categoryId}


        AND p.ISSUER LIKE CONCAT('%', #{params.issuer}, '%')


        AND p.CURRENCY_CODE = #{params.currencyCode}


        AND p.RISK_LEVEL = #{params.riskLevel}


        AND p.PRODUCT_STATUS = #{params.productStatus}


        AND p.SHELF_STATUS = #{params.shelfStatus}


ORDER BY p.CREATE_TIME DESC

SELECT COUNT(1)
FROM TBL_FINANCIAL_PRODUCT
WHERE PRODUCT_CODE = #{productCode}

    AND PRODUCT_ID != #{excludeId}

